      const module = buildSemanticCensus(fixture.root, {}, fixture.taxonomy).records.find((record) => record.id === "measure");
      expect(module?.productionConsumers).toEqual(["width"]);
      expect(module?.excludedConsumers).toEqual(["width"]);
